"git+https://github.com/Alan2Z/dsh-speak.git\"\n  },\n  \"author\": \"Alan2Z\",\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"publishConfig\": {\n    \"registry\": \"https://registry.npmjs.org\"\n  }\n}\n"
